css:
:root{--studio-page:#fff;--studio-bar:#f5f5f7;--studio-side:#f0f0f2;--studio-card:#fafafa;--studio-msg:#f2f2f5;--studio-rule:#0000001c;--studio-shadow:#0000000d}
.dark{--studio-page:#131315;--studio-bar:#1c1c1e;--studio-side:#202022;--studio-card:#222225;--studio-msg:#252528;--studio-rule:#ffffff1b;--studio-shadow:#00000028}
[data-workspace-area="conversation"]{background:var(--studio-page)!important}
[data-slot="sidebar-inner"]{background:var(--studio-side)!important;box-shadow:inset -1px 0 var(--studio-rule)}
[data-chat-header]{background:var(--studio-bar)!important;box-shadow:inset 0 -1px var(--studio-rule)}
[data-slot="composer-host"],[data-thread-details-card]{background:var(--studio-card)!important;border:1px solid var(--studio-rule)!important;border-radius:12px!important;box-shadow:0 2px 6px var(--studio-shadow)!important;backdrop-filter:none}
[data-user-message-bubble]{background:var(--studio-msg)!important;border-radius:12px!important;box-shadow:none!important}
[data-slot="menu-popup"],[data-slot="popover-popup"]{border:1px solid var(--studio-rule)!important;border-radius:10px!important}

/* Outgoing bubble color experiment */
:root{--studio-msg:#d9e9ff}
.dark{--studio-msg:#264971}
